SELECT gt0.gif_id
FROM gif_tag gt0


        INNER JOIN gif_tag gt${index} ON gt0.gif_id = gt${index}.gif_id AND gt${index}.tag_id = #{tagId}


INNER JOIN gif g ON gt0.gif_id = g.id



            gt0.tag_id = #{tagId}



        AND (g.created_at < #{lastCreatedAt} OR (g.created_at = #{lastCreatedAt} AND gt0.gif_id < #{lastId}))

    AND g.status = 1

ORDER BY g.created_at DESC, gt0.gif_id DESC
LIMIT #{pageSize}

SELECT gt0.gif_id
FROM gif_tag gt0


        INNER JOIN gif_tag gt${index} ON gt0.gif_id = gt${index}.gif_id AND gt${index}.tag_id = #{tagId}


INNER JOIN gif g ON gt0.gif_id = g.id



            gt0.tag_id = #{tagId}


    AND g.status = 1

ORDER BY g.like_count DESC, gt0.gif_id DESC
LIMIT #{pageSize} OFFSET #{offset}
